// The std:string standard library package (Go's strings, camelCase names).
package examples.strings;

use "std:string";

public string slug(string title) {
    string s = string.toLower(string.trimSpace(title));
    return string.replaceAll(s, " ", "-");
}

public int main() {
    string title = "   Hello RuneScript World   ";
    trace("slug:", slug(title));

    string path = "assets/runescript.svg";
    if (string.hasSuffix(path, ".svg")) {
        trace("image:", string.trimSuffix(path, ".svg"));
    }

    int slash = string.index(path, "/");
    trace("first slash at byte", slash);
    trace("vowels in title:", string.count(title, "o") + string.count(title, "e"));
    trace(string.repeat("=", 20));
    return 0;
}

// Floats and conversions: a temperature table.
package examples;

public float toFahrenheit(float celsius) {
    return celsius * 9 / 5 + 32;
}

public int main() {
    for (int c = -40; c <= 100; c += 35) {
        float f = toFahrenheit((float) c);
        trace(c, "C is", f, "F");
    }

    // float32 keeps 32-bit precision; float keeps every digit.
    float exact = 1.0 / 3;
    float32 rounded = (float32) exact;
    trace(exact, rounded);

    // Conversions are checked and truncate toward zero.
    trace((int) toFahrenheit(37.5), (int) -2.9, (float) "98.6");
    return 0;
}

// Declarations, assignment, and compound assignment.
package examples.variables;

public int main() {
    int count = 10;
    sint offset = -3;          // 'sint' is another spelling of 'int'
    uint total = 0;
    string label = "count";
    bool ready = true;

    count = count + offset;    // 7
    count *= 2;                // 14
    count++;                   // 15
    total += 40;

    trace(label, count);
    trace("total", total);
    trace("ready", ready);
    return 0;
}
